const std::vector<CameraRawParameter>& cameraRawParameters(){static const auto parameters=[] {
    std::vector<CameraRawParameter> p;auto add=[&](const char*g,const char*k,const char*l,double lo=-100,double hi=100,double initial=0){p.push_back({g,k,l,lo,hi,initial});};
    add("Light","exposure","Exposure",-5,5);for(auto pair:{std::pair{"contrast","Contrast"},{"highlights","Highlights"},{"shadows","Shadows"},{"whites","Whites"},{"blacks","Blacks"}})add("Light",pair.first,pair.second);
    for(auto pair:{std::pair{"temperature","Temperature"},{"tint","Tint"},{"vibrance","Vibrance"},{"saturation","Saturation"}})add("Color",pair.first,pair.second);
    for(auto pair:{std::pair{"texture","Texture"},{"clarity","Clarity"},{"dehaze","Dehaze"},{"glowRange","Glow range"},{"glowSpread","Glow spread"},{"glowWarmth","Glow warmth"},{"vignetteAmount","Vignette amount"},{"vignetteRoundness","Vignette roundness"}})add("Effects",pair.first,pair.second);
    add("Effects","glow","Glow",0,100);add("Effects","glowStyle","Glow style",0,2);add("Effects","vignetteStyle","Vignette style",0,2);add("Effects","vignetteMidpoint","Vignette midpoint",0,100,50);add("Effects","vignetteFeather","Vignette feather",0,100,50);add("Effects","vignetteHighlights","Vignette highlights",0,100);add("Effects","grainAmount","Grain amount",0,100);add("Effects","grainSize","Grain size",0,100,25);add("Effects","grainRoughness","Grain roughness",0,100,50);
    add("Curve","curveShadows","Shadows");add("Curve","curveDarks","Darks");add("Curve","curveLights","Lights");add("Curve","curveHighlights","Highlights");add("Curve","shadowSplit","Shadow split",5,90,25);add("Curve","darkSplit","Dark split",7,95,50);add("Curve","lightSplit","Light split",9,98,75);add("Curve","refineSaturation","Refine saturation",-100,100);
    static const char* mixerKeys[3][8]={{"redHue","orangeHue","yellowHue","greenHue","aquaHue","blueHue","purpleHue","magentaHue"},{"redSaturation","orangeSaturation","yellowSaturation","greenSaturation","aquaSaturation","blueSaturation","purpleSaturation","magentaSaturation"},{"redLuminance","orangeLuminance","yellowLuminance","greenLuminance","aquaLuminance","blueLuminance","purpleLuminance","magentaLuminance"}};
    static const char* mixerLabels[3][8]={{"Red hue","Orange hue","Yellow hue","Green hue","Aqua hue","Blue hue","Purple hue","Magenta hue"},{"Red saturation","Orange saturation","Yellow saturation","Green saturation","Aqua saturation","Blue saturation","Purple saturation","Magenta saturation"},{"Red luminance","Orange luminance","Yellow luminance","Green luminance","Aqua luminance","Blue luminance","Purple luminance","Magenta luminance"}};
    for(int a=0;a<3;++a)for(int c=0;c<8;++c)add("Mixer",mixerKeys[a][c],mixerLabels[a][c]);
    static const char* gradeKeys[4][3]={{"gradeShadowHue","gradeShadowSaturation","gradeShadowLuminance"},{"gradeMidtoneHue","gradeMidtoneSaturation","gradeMidtoneLuminance"},{"gradeHighlightHue","gradeHighlightSaturation","gradeHighlightLuminance"},{"gradeGlobalHue","gradeGlobalSaturation","gradeGlobalLuminance"}};
    static const char* gradeLabels[4][3]={{"Shadows hue","Shadows saturation","Shadows luminance"},{"Midtones hue","Midtones saturation","Midtones luminance"},{"Highlights hue","Highlights saturation","Highlights luminance"},{"Global hue","Global saturation","Global luminance"}};
    for(int wheel=0;wheel<4;++wheel)for(int c=0;c<3;++c)add("Grading",gradeKeys[wheel][c],gradeLabels[wheel][c],c==2?-100:0,c==0?360:100);add("Grading","gradeBlending","Blending",0,100,50);add("Grading","gradeBalance","Balance");
    add("Detail","sharpenAmount","Sharpening amount",0,150);add("Detail","sharpenRadius","Sharpening radius",0,100,10);add("Detail","sharpenDetail","Sharpening detail",0,100,25);add("Detail","sharpenMasking","Sharpening masking",0,100);add("Detail","noiseLuminance","Noise luminance",0,100);add("Detail","noiseLuminanceDetail","Luminance detail",0,100,50);add("Detail","noiseLuminanceContrast","Luminance contrast",0,100);add("Detail","noiseColor","Color noise",0,100);add("Detail","noiseColorDetail","Color detail",0,100,50);add("Detail","noiseColorSmoothness","Color smoothness",0,100,50);
    add("Optics","removeChromatic","Remove chromatic aberration",0,1);add("Optics","lensProfile","Enable generic lens correction",0,1);add("Optics","profileDistortion","Profile distortion",0,100,100);add("Optics","profileVignetting","Profile vignetting",0,100,100);add("Optics","distortion","Distortion");add("Optics","purpleAmount","Purple defringe",0,100);add("Optics","purpleHueLow","Purple hue start",0,360,270);add("Optics","purpleHueHigh","Purple hue end",0,360,310);add("Optics","greenAmount","Green defringe",0,100);add("Optics","greenHueLow","Green hue start",0,360,60);add("Optics","greenHueHigh","Green hue end",0,360,120);add("Optics","opticsVignette","Lens vignette");add("Optics","opticsMidpoint","Lens vignette midpoint",0,100,50);
    add("Geometry","upright","Guided upright",0,1);add("Geometry","projection","Rectilinear projection",0,1);add("Geometry","vertical","Vertical");add("Geometry","horizontal","Horizontal");add("Geometry","rotate","Rotate",-45,45);add("Geometry","aspect","Aspect");add("Geometry","scale","Scale");add("Geometry","offsetX","Horizontal offset");add("Geometry","offsetY","Vertical offset");add("Geometry","constrainCrop","Constrain crop",0,1);
    add("Calibration","process","Process version",1,6,6);add("Calibration","shadowTint","Shadow tint");add("Calibration","primaryRedHue","Red primary hue");add("Calibration","primaryRedSaturation","Red primary saturation");add("Calibration","primaryGreenHue","Green primary hue");add("Calibration","primaryGreenSaturation","Green primary saturation");add("Calibration","primaryBlueHue","Blue primary hue");add("Calibration","primaryBlueSaturation","Blue primary saturation");return p;
}();return parameters;}
CameraRawSettings::CameraRawSettings(){for(const auto& p:cameraRawParameters())values[p.key]=p.initial;for(auto& curve:curves)curve={{0,0},{255,255}};}
double CameraRawSettings::get(std::string_view key)const{auto found=values.find(key);if(found==values.end())throw std::runtime_error("Unknown Camera Raw setting");return found->second;}
void CameraRawSettings::set(std::string_view key,double value){auto found=std::find_if(cameraRawParameters().begin(),cameraRawParameters().end(),[&](const auto& p){return key==p.key;});if(found==cameraRawParameters().end()||!std::isfinite(value)||value<found->minimum||value>found->maximum)throw std::runtime_error("Invalid Camera Raw setting");values[std::string(key)]=value;}
bool CameraRawSettings::identity()const{CameraRawSettings neutral;return values==neutral.values&&curves==neutral.curves&&points.empty()&&guides.empty();}
