QImage geometry(const QImage& input,const CameraRawSettings& s){
    double vertical=s.get("vertical"),horizontal=s.get("horizontal"),rotation=s.get("rotate");if(s.get("upright")&&!s.guides.empty()){auto [a,b]=s.guides[0];const auto dx=b.x-a.x,dy=b.y-a.y;if(std::hypot(dx,dy)>.01){double angle=-std::atan2(dy,dx)*180/std::numbers::pi;if(angle>45)angle-=90;else if(angle< -45)angle+=90;rotation+=angle;}if(s.guides.size()>1){auto [c,d]=s.guides[1];double angle=std::atan2(d.y-c.y,d.x-c.x)*180/std::numbers::pi;if(std::hypot(d.y-c.y,d.x-c.x)>.01){if(std::abs(angle)>45)vertical+=angle>0?25:-25;else horizontal+=angle>0?25:-25;}}}
    if(vertical==0&&horizontal==0&&rotation==0&&s.get("aspect")==0&&s.get("scale")==0&&s.get("offsetX")==0&&s.get("offsetY")==0)return input;
    const double w=input.width(),h=input.height(),strength=s.get("projection")?.55:1,v=vertical/100*w*.18*strength,hz=horizontal/100*h*.18*strength,shiftX=s.get("offsetX")/100*w*.15,shiftY=s.get("offsetY")/100*h*.15,cx=w/2+shiftX,cy=h/2+shiftY,aspect=1+s.get("aspect")/200,zoom=1+s.get("scale")/100,rad=rotation*std::numbers::pi/180;
    QPolygonF quad;for(auto [x,y]:{Point{-v+shiftX,h+shiftY},Point{w+v+shiftX,h+shiftY},Point{w+hz+shiftX,-shiftY},Point{-hz+shiftX,-shiftY}}){const double dx=x-cx,dy=y-cy,rx=cx+dx*std::cos(rad)-dy*std::sin(rad),ry=cy+dx*std::sin(rad)+dy*std::cos(rad);quad<<QPointF(cx+(rx-cx)*aspect*zoom,h-(cy+(ry-cy)/aspect*zoom));}
    if(zoom<=0){QImage blank(input.size(),input.format());blank.fill(Qt::transparent);return blank;}QTransform transform;if(!QTransform::quadToQuad(QPolygonF{QPointF(0,0),QPointF(w,0),QPointF(w,h),QPointF(0,h)},quad,transform))return input;QImage output(input.size(),input.format());output.fill(Qt::transparent);QPainter p(&output);p.setRenderHint(QPainter::SmoothPixmapTransform);p.setTransform(transform);p.drawImage(0,0,input);p.end();
    if(s.get("constrainCrop")){int left=output.width(),top=output.height(),right=0,bottom=0;for(int y=0;y<output.height();++y){auto row=output.constScanLine(y);for(int x=0;x<output.width();++x)if(row[x*4+3]){left=std::min(left,x);top=std::min(top,y);right=std::max(right,x+1);bottom=std::max(bottom,y+1);}}if(right>left&&bottom>top&&(right-left<output.width()||bottom-top<output.height())){auto cropped=output.copy(left,top,right-left,bottom-top).scaled(output.size(),Qt::KeepAspectRatio,Qt::SmoothTransformation);output.fill(Qt::transparent);QPainter painter(&output);painter.drawImage((output.width()-cropped.width())/2,(output.height()-cropped.height())/2,cropped);}}
    return output;
}
