std::shared_ptr<const Raster> applyCameraRaw(const Raster& image,const CameraRawSettings& s,double scale,CameraRawPreview view,std::function<bool()> cancelled){
    auto check=[&]{if(cancelled&&cancelled())throw std::runtime_error("Camera Raw cancelled");};check();if(!std::isfinite(scale)||scale<=0)throw std::runtime_error("Invalid Camera Raw preview scale");for(const auto& p:cameraRawParameters()){const auto v=s.get(p.key);if(!std::isfinite(v)||v<p.minimum||v>p.maximum)throw std::runtime_error("Invalid Camera Raw parameter");}for(const auto& curve:s.curves)if(!effects_tools::validCurve(curve))throw std::runtime_error("Invalid Camera Raw curve");if(s.points.size()>32||s.guides.size()>4)throw std::runtime_error("Camera Raw point/guide budget exceeded");if(s.identity()&&!view.clipping&&view.pointColor<0&&!view.sharpenMask&&!view.shadowOverlay&&!view.highlightOverlay)return std::make_shared<Raster>(image);
    auto bytes=image.rgba();QImage input(bytes.data(),image.width,image.height,image.width*4,QImage::Format_RGBA8888_Premultiplied);QImage output=(!view.clipping&&!view.sharpenMask&&view.pointColor<0?geometry(input,s):input).copy();auto* p=output.bits();const auto w=size_t(output.width()),h=size_t(output.height()),stride=size_t(output.bytesPerLine());auto v=[&](const char* key){return s.get(key);};
    if(!view.clipping&&!view.sharpenMask)adjust_camera_raw_calibration(p,w,h,stride,v("shadowTint"),v("primaryRedHue"),v("primaryRedSaturation"),v("primaryGreenHue"),v("primaryGreenSaturation"),v("primaryBlueHue"),v("primaryBlueSaturation"),int(v("process")));check();
    const auto warm=v("temperature")/100,magenta=v("tint")/100;adjust_camera_raw(p,w,h,stride,1+.35*warm+.15*magenta,1-.30*magenta,1-.35*warm+.15*magenta,v("exposure"),v("contrast"),v("highlights"),v("shadows"),v("whites"),v("blacks"),v("vibrance"),v("saturation"),view.clipping);check();
    if(!view.clipping&&!view.sharpenMask){std::array<std::array<float,256>,4> lut;std::array<double,3> splits{v("shadowSplit")/100,v("darkSplit")/100,v("lightSplit")/100};splits[0]=std::clamp(splits[0],.05,.90);splits[1]=std::clamp(splits[1],splits[0]+.02,.95);splits[2]=std::clamp(splits[2],splits[1]+.02,.98);std::array<double,5> edges{0,splits[0],splits[1],splits[2],1};std::array<double,4> amount{v("curveShadows"),v("curveDarks"),v("curveLights"),v("curveHighlights")};for(int i=0;i<256;++i){double tone=i/255.;int region=tone<edges[1]?0:tone<edges[2]?1:tone<edges[3]?2:3;const double lo=edges[size_t(region)],hi=edges[size_t(region+1)],weight=std::max(0.,1-std::abs(tone-(lo+hi)/2)/(std::max(.02,hi-lo)/2));lut[0][size_t(i)]=float(effects_tools::curveValueUnchecked(s.curves[0],std::clamp(tone+amount[size_t(region)]/100*weight*.22,0.,1.)*255)/255);for(int c=1;c<4;++c)lut[size_t(c)][size_t(i)]=float(effects_tools::curveValueUnchecked(s.curves[size_t(c)],i)/255);}
        std::array<float,24> mixer;size_t index=0;for(const auto* channel:{"Hue","Saturation","Luminance"})for(const auto* color:{"red","orange","yellow","green","aqua","blue","purple","magenta"})mixer[index++]=float(s.get(std::string(color)+channel)/100);
        std::array<float,12> grade;index=0;for(const auto* wheel:{"Shadow","Midtone","Highlight","Global"})for(const auto* channel:{"Hue","Saturation","Luminance"})grade[index++]=float(s.get(std::string("grade")+wheel+channel)/(std::string_view(channel)=="Hue"?360:100));
        std::vector<float> points;for(const auto& point:s.points)for(double x:{point.hue/360,point.saturation,point.luminance,point.hueShift/100,point.saturationShift/100,point.luminanceShift/100,point.hueRange/360,point.saturationRange,point.luminanceRange}){if(!std::isfinite(x))throw std::runtime_error("Invalid Camera Raw point color");points.push_back(float(x));}
        adjust_camera_raw_curve_color(p,w,h,stride,lut[0].data(),lut[1].data(),lut[2].data(),lut[3].data(),v("refineSaturation")/100,mixer.data(),int(s.points.size()),points.data(),grade.data(),v("gradeBlending")/100,v("gradeBalance")/100,view.pointColor);check();
        adjust_camera_raw_effects(p,w,h,stride,v("texture"),v("clarity"),v("dehaze"),v("glow"),int(v("glowStyle")),v("glowRange"),v("glowSpread"),v("glowWarmth"),v("vignetteAmount"),v("vignetteMidpoint"),v("vignetteRoundness"),v("vignetteFeather"),v("vignetteHighlights"),int(v("vignetteStyle")),scale);if(v("grainAmount")>0)adjust_grain(p,w,h,stride,v("grainAmount"),.5+v("grainSize")/100*19.5,v("grainRoughness"),0x43414d52,0,0,1/scale);check();
    }
    if(!view.clipping){if(view.sharpenMask)adjust_camera_raw_sharpen_mask_overlay(p,w,h,stride,v("sharpenRadius"),v("sharpenDetail"),v("sharpenMasking"),scale);else{
        if(v("removeChromatic")||v("lensProfile")||v("distortion")||v("purpleAmount")||v("greenAmount")||v("opticsVignette"))adjust_camera_raw_optics(p,w,h,stride,int(v("removeChromatic")),int(v("lensProfile")),v("profileDistortion"),v("profileVignetting"),v("distortion")/100*.35+(v("lensProfile")?v("profileDistortion")/100*.35:0),v("purpleAmount"),std::min(v("purpleHueLow"),v("purpleHueHigh")),std::max(v("purpleHueLow"),v("purpleHueHigh")),v("greenAmount"),std::min(v("greenHueLow"),v("greenHueHigh")),std::max(v("greenHueLow"),v("greenHueHigh")),v("opticsVignette"),v("opticsMidpoint"),scale);check();
        if(v("sharpenAmount")||v("noiseLuminance")||v("noiseColor"))adjust_camera_raw_detail(p,w,h,stride,v("sharpenAmount"),v("sharpenRadius"),v("sharpenDetail"),v("sharpenMasking"),v("noiseLuminance"),v("noiseLuminanceDetail"),v("noiseLuminanceContrast"),v("noiseColor"),v("noiseColorDetail"),v("noiseColorSmoothness"),scale);
    }}if(view.shadowOverlay||view.highlightOverlay)adjust_camera_raw_clip_overlay(p,w,h,stride,view.shadowOverlay,view.highlightOverlay);check();rgba_clamp_premultiplied(p,w*h);return Raster::fromRgba(int(w),int(h),p,stride);
}
std::optional<Point> cameraRawWhiteBalance(const Raster& image,std::optional<Point> sample){
    double red=0,green=0,blue=0,count=0;auto linear=[](double x){return x<=.04045?x/12.92:std::pow((x+.055)/1.055,2.4);};auto add=[&](int x,int y){auto p=image.pixel(x,y);if(p.a){red+=linear(p.r/double(p.a));green+=linear(p.g/double(p.a));blue+=linear(p.b/double(p.a));++count;}};if(sample){for(int y=std::max(0,int(sample->y)-2);y<std::min(image.height,int(sample->y)+3);++y)for(int x=std::max(0,int(sample->x)-2);x<std::min(image.width,int(sample->x)+3);++x)add(x,y);}else{int step=std::max(1,int(std::sqrt(double(image.width)*image.height/1000000)));for(int y=0;y<image.height;y+=step)for(int x=0;x<image.width;x+=step)add(x,y);}if(!count)return {};red/=count;green/=count;blue/=count;if(std::min({red,green,blue})<1e-4)return {};const auto a1=.35*red,b1=.15*red+.30*green,c1=green-red,a2=-.35*blue,b2=.15*blue+.30*green,c2=green-blue,det=a1*b2-a2*b1;if(std::abs(det)<1e-8)return {};return Point{std::clamp((c1*b2-c2*b1)/det*100,-100.,100.),std::clamp((a1*c2-a2*c1)/det*100,-100.,100.)};
}
std::string encodeCameraRawSettings(const CameraRawSettings& settings){QJsonObject object;for(const auto& [key,value]:settings.values)object[QString::fromStdString(key)]=value;QJsonArray curves;for(const auto& points:settings.curves){QJsonArray curve;for(const auto& p:points)curve.append(QJsonArray{p.x,p.y});curves.append(curve);}object["curves"]=curves;QJsonArray colors;for(const auto& p:settings.points)colors.append(QJsonArray{p.hue,p.saturation,p.luminance,p.hueShift,p.saturationShift,p.luminanceShift,p.hueRange,p.saturationRange,p.luminanceRange});object["points"]=colors;QJsonArray guides;for(const auto& [a,b]:settings.guides)guides.append(QJsonArray{a.x,a.y,b.x,b.y});object["guides"]=guides;return QJsonDocument(object).toJson(QJsonDocument::Compact).toStdString();}
CameraRawSettings decodeCameraRawSettings(std::string_view json){if(json.size()>65536)throw std::runtime_error("Camera Raw settings exceed budget");const auto doc=QJsonDocument::fromJson(QByteArray(json.data(),qsizetype(json.size())));if(!doc.isObject())throw std::runtime_error("Invalid Camera Raw settings");CameraRawSettings result;auto object=doc.object();for(const auto& p:cameraRawParameters())if(object.contains(p.key))result.set(p.key,object[p.key].toDouble(std::numeric_limits<double>::quiet_NaN()));const auto curves=object["curves"].toArray();if(!curves.isEmpty()){if(curves.size()!=4)throw std::runtime_error("Invalid Camera Raw curve count");for(int c=0;c<4;++c){result.curves[size_t(c)].clear();for(auto point:curves[c].toArray()){auto a=point.toArray();if(a.size()!=2)throw std::runtime_error("Invalid curve point");result.curves[size_t(c)].push_back({a[0].toDouble(),a[1].toDouble()});}if(!effects_tools::validCurve(result.curves[size_t(c)]))throw std::runtime_error("Invalid Camera Raw curve");}}for(auto item:object["points"].toArray()){auto a=item.toArray();if(a.size()!=9||result.points.size()>=32)throw std::runtime_error("Invalid point color");result.points.push_back({a[0].toDouble(),a[1].toDouble(),a[2].toDouble(),a[3].toDouble(),a[4].toDouble(),a[5].toDouble(),a[6].toDouble(),a[7].toDouble(),a[8].toDouble()});}for(auto item:object["guides"].toArray()){auto a=item.toArray();if(a.size()!=4||result.guides.size()>=4)throw std::runtime_error("Invalid upright guide");result.guides.push_back({{a[0].toDouble(),a[1].toDouble()},{a[2].toDouble(),a[3].toDouble()}});}return result;}
